patch:
diff --git a/recreate/no-var-tdz.check.js b/recreate/no-var-tdz.check.js
new file mode 100644
index 0000000..690f500
--- /dev/null
+++ b/recreate/no-var-tdz.check.js
@@ -0,0 +1,79 @@
+"use strict";
+
+/*
+ * Check for "[no-var] Fix causes ReferenceError".
+ *
+ * Applies the `no-var` autofix to the report's code and then RUNS the result.
+ * Expected: the autofix must not turn code that runs fine into code that throws
+ * a ReferenceError (either leave it unfixed or fix it safely).
+ *
+ * Usage (from the repo root):
+ *   node recreate/no-var-tdz.check.js                       # eslint from this checkout
+ *   ESLINT_DIR=/path/to/node_modules/eslint node recreate/no-var-tdz.check.js
+ */
+
+const path = require("node:path");
+const vm = require("node:vm");
+
+const eslintDir = path.resolve(process.env.ESLINT_DIR || ".");
+const { ESLint } = require(path.join(eslintDir, "lib", "api.js"));
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+/**
+ * Runs the report's function (minus the `export` keyword) and returns the error thrown, if any.
+ * @param {string} source Source text.
+ * @returns {Error|null} The thrown error or null.
+ */
+function run(source) {
+	const sandbox = { console: { log() {} } };
+
+	try {
+		vm.runInNewContext(
+			`${source.replace(/^export /mu, "")}\na();`,
+			sandbox,
+		);
+		return null;
+	} catch (error) {
+		return error;
+	}
+}
+
+(async () => {
+	const eslint = new ESLint({
+		cwd: process.cwd(),
+		overrideConfigFile: true,
+		overrideConfig: [{ rules: { "no-var": "error" } }],
+		fix: true,
+	});
+	const [result] = await eslint.lintText(code, { filePath: "a.js" });
+	const output = result.output ?? code;
+
+	console.log(`eslint ${ESLint.version}`);
+	console.log("--- code after --fix ---");
+	console.log(output);
+
+	const before = run(code);
+	const after = run(output);
+
+	if (before) {
+		console.error(
+			`SETUP ERROR: original code already throws: ${before.name}`,
+		);
+		process.exit(2);
+	}
+
+	if (after) {
+		console.error(
+			`FAIL: autofixed code throws ${after.name}: ${after.message}`,
+		);
+		process.exit(1);
+	}
+
+	console.log("PASS: autofixed code still runs without error");
+})();
